<script setup>
defineOptions({
  name: 'AlertSection'
})

import { ref, onMounted, onUnmounted } from 'vue'
import AlertVarian from '@/components/Alert/AlertVarian.vue'
import Button from '@/components/Button/Button.vue'

const showAlertDismissible = ref(true)
const countdownSec = ref(10)
let timer = null

onMounted(() => {
  timer = setInterval(() => {
    if (countdownSec.value > 1) {
      countdownSec.value--
    } else {
      showAlertDismissible.value = false
    }
  }, 1000)
})

onUnmounted(() => {
  if (timer) clearInterval(timer)
})

const resetDismissible = () => {
  countdownSec.value = 10
  showAlertDismissible.value = true
}

const handleActionClick = () => {
  alert('Rincian tarif sewa modal dibuka.')
}

const handlePrint = () => {
  alert('Surat Bukti Gadai (SBG) siap dicetak.')
}
</script>

