<script setup>
import { ref, computed } from 'vue'
import InputFilter from '@/components/Filter/InputFilter.vue'
import DateRangePickerOption from '@/components/Input/DateRangePickerOption.vue'
import InputSearch from '@/components/Input/InputSearch.vue'
import Dropdown from '@/components/Dropdown/InputDropdown.vue'
import Button from '@/components/Button/Button.vue'
import Badge from '@/components/Badge/Badge.vue'

// Varian 1 State & Options (3 Field: InputFilter + Dropdown + InputSearch)
const filterState1 = ref({
  startDate: '',
  endDate: ''
})
const labelFilter1 = ref('')
const handleDateFilter1 = (val) => {
  labelFilter1.value = val
}
const v1Agunan = ref('')
const v1Search = ref('')
const agunanOptions = [
  { value: '', text: 'Semua Kategori Agunan' },
  { value: 'emas', text: 'Perhiasan Emas & Logam Mulia' },
  { value: 'elektronik', text: 'Elektronik & Gadget' },
  { value: 'kendaraan', text: 'Kendaraan Bermotor' }
]

// Varian 2 State & Options (3 Field: DateRangePickerOption + Dropdown Status + Dropdown Loket)
const v2Status = ref('')
const v2Loket = ref('')
const statusOptions = [
  { value: '', text: 'Semua Status' },
  { value: 'lunas', text: 'Lunas Selesai' },
  { value: 'perpanjang', text: 'Perpanjangan Uang Sewa' },
  { value: 'lelang', text: 'Siap Eksekusi Lelang' }
]
const loketOptions = [
  { value: '', text: 'Semua Loket Kasir' },
  { value: 'loket1', text: 'Loket 01 - Kasir Emas' },
  { value: 'loket2', text: 'Loket 02 - Gadai Kilat' },
  { value: 'loket3', text: 'Loket 03 - Tebusan Lelang' }
]

// Real Case State & Data (3 Field: DateRangePickerOption + Dropdown + InputSearch)
const rcFilterJenis = ref('')
const rcFilterSearch = ref('')

const rcJenisOptions = [
  { value: '', text: 'Semua Jenis Transaksi' },
  { value: 'Pelunasan Penuh', text: 'Pelunasan Penuh' },
  { value: 'Perpanjangan Gadai (Sewa Modal)', text: 'Perpanjangan Gadai (Sewa Modal)' }
]

const masterKasirList = [
  { tgl: '02/09/2026', sbg: '10234-26-01-000881', jenis: 'Pelunasan Penuh', nominal: 'Rp 5.240.000', kasir: 'Kasir UPK 01' },
  { tgl: '01/09/2026', sbg: '10234-26-01-000882', jenis: 'Perpanjangan Gadai (Sewa Modal)', nominal: 'Rp 185.000', kasir: 'Kasir UPK 02' },
  { tgl: '30/08/2026', sbg: '10234-26-01-000883', jenis: 'Pelunasan Penuh', nominal: 'Rp 12.800.000', kasir: 'Kasir UPK 01' },
  { tgl: '28/08/2026', sbg: '10234-26-01-000884', jenis: 'Perpanjangan Gadai (Sewa Modal)', nominal: 'Rp 340.000', kasir: 'Kasir UPK 03' }
]

const filteredKasirList = computed(() => {
  return masterKasirList.filter(item => {
    const matchJenis = !rcFilterJenis.value || item.jenis === rcFilterJenis.value
    const matchSearch = !rcFilterSearch.value ||
      item.sbg.toLowerCase().includes(rcFilterSearch.value.toLowerCase()) ||
      item.kasir.toLowerCase().includes(rcFilterSearch.value.toLowerCase())
    return matchJenis && matchSearch
  })
})

const resetRcFilter = () => {
  rcFilterJenis.value = ''
  rcFilterSearch.value = ''
}

const cetakRekapSimulasi = () => {
  alert(`Mencetak rekap transaksi kasir (${filteredKasirList.value.length} data)...`)
}
</script>
