<!--
  Fungsi: InputNominalStart adalah komponen input nilai mata uang (rupiah) dengan label satuan/unit di awal (prefix)
  serta pemformatan pemisah ribuan otomatis (titik) saat pengguna mengetik.
  Biasa dipakai pada: Pengisian taksiran nilai pasar barang agunan emas, plafon maksimal pinjaman, atau saldo rekening.
-->

<template>
  <section class="playground-section card shadow-sm border mb-5" id="section-input-nominal-start">
    <!-- Card Header: Judul Komponen, Kategori, dan Deskripsi Singkat -->
    <div class="card-header bg-white py-3 border-bottom">
      <div class="d-flex flex-column flex-sm-row align-items-start align-items-sm-center justify-content-between gap-2 mb-2">
        <div class="d-flex flex-wrap align-items-center gap-2">
          <h4 class="fw-bold mb-0 text-dark">InputNominalStart</h4>
          <code class="text-secondary small">&lt;InputNominalStart /&gt;</code>
        </div>
        <span class="badge bg-primary-subtle text-primary border">form-text</span>
      </div>
      <p class="text-muted small mb-0">
        Input nominal mata uang dengan prefix satuan di sisi kiri dan pemformatan desimal/ribuan otomatis.
      </p>
    </div>

    <!-- Card Body: Memuat 3 Bagian (Tabel Props, Varian State, dan Real Case) -->
    <div class="card-body p-3 p-md-4">
      <!-- 1. TABEL PROPS YANG DIDUKUNG (FULL WIDTH VIA .props-table) -->
      <div class="mb-4">
        <h6 class="fw-semibold text-secondary small text-uppercase mb-2">1. Daftar Props yang Didukung</h6>
        <div class="table-responsive w-100 rounded border">
          <table class="props-table">
            <thead>
              <tr>
                <th style="width: 20%; min-width: 140px;">Prop Name</th>
                <th style="width: 22%; min-width: 150px;">Type / Format</th>
                <th style="width: 15%; min-width: 100px;">Default</th>
                <th style="min-width: 200px;">Keterangan</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td><code>modelValue</code></td>
                <td><code>String | Number</code></td>
                <td><code>''</code></td>
                <td>Nilai numerik mentah tanpa tanda titik (two-way binding via <code>v-model</code>).</td>
              </tr>
              <tr>
                <td><code>unit</code></td>
                <td><code>String</code></td>
                <td><code>'Rupiah'</code></td>
                <td>Label teks satuan prefix di sisi kiri (mis. 'Rp', 'Rupiah', 'IDR').</td>
              </tr>
              <tr>
                <td><code>placeholder</code></td>
                <td><code>String</code></td>
                <td><code>'Masukkan rupiah'</code></td>
                <td>Teks placeholder ketika input kosong.</td>
              </tr>
              <tr>
                <td><code>class</code></td>
                <td><code>String</code></td>
                <td><code>''</code></td>
                <td>Kelas CSS kustom untuk styling kontainer input.</td>
              </tr>
              <tr>
                <td><code>disabled</code></td>
                <td><code>Boolean</code></td>
                <td><code>false</code></td>
                <td>Menonaktifkan interaksi (diteruskan via <code>$attrs</code>).</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      <!-- 2. VARIAN STATE KOMPONEN (3-5 VARIAN BERMAKNA) -->
      <div class="mb-4">
        <h6 class="fw-semibold text-secondary small text-uppercase mb-2">2. Varian State Komponen</h6>
        <div class="p-3 bg-light rounded border">
          <div class="row g-4">
            <!-- Varian 1: Default Unit 'Rupiah' -->
            <div class="col-12 col-md-6">
              <label class="form-label small fw-semibold text-muted mb-1">Default Unit ('Rupiah')</label>
              <InputNominalStart
                id="nom-start-default"
                v-model="stateDefault"
                placeholder="Masukkan nominal taksiran..."
              />
              <div class="text-muted small mt-1">Raw Value: <code>{{ stateDefault || '0' }}</code></div>
            </div>

            <!-- Varian 2: Custom Unit ('Rp') -->
            <div class="col-12 col-md-6">
              <label class="form-label small fw-semibold text-muted mb-1">Custom Unit ('Rp')</label>
              <InputNominalStart
                id="nom-start-rp"
                v-model="stateRp"
                unit="Rp"
                placeholder="Contoh: 15.000.000"
              />
              <div class="text-muted small mt-1">Raw Value: <code>{{ stateRp || '0' }}</code></div>
            </div>

            <!-- Varian 3: Pre-filled Nominal -->
            <div class="col-12 col-md-6">
              <label class="form-label small fw-semibold text-muted mb-1">Pre-filled Nominal</label>
              <InputNominalStart
                id="nom-start-filled"
                v-model="stateFilled"
                unit="Rp"
              />
              <div class="text-muted small mt-1">Raw Value: <code>{{ stateFilled }}</code></div>
            </div>

            <!-- Varian 4: Disabled State -->
            <div class="col-12 col-md-6">
              <label class="form-label small fw-semibold text-muted mb-1">Disabled State (Nilai Terkunci)</label>
              <InputNominalStart
                id="nom-start-disabled"
                v-model="stateDisabled"
                unit="Rp"
                :disabled="true"
              />
              <div class="text-muted small mt-1">Nilai terkunci dari sistem pusat.</div>
            </div>
          </div>
        </div>
      </div>

      <!-- 3. REAL CASE: SIMULASI KONTEKS BISNIS PEGADAIAN -->
      <div>
        <div class="d-flex flex-column flex-sm-row align-items-start align-items-sm-center justify-content-between gap-2 mb-2">
          <h6 class="fw-bold text-success small text-uppercase mb-0">
            3. Real Case: Perhitungan Taksiran Nilai Agunan Emas Batangan 24K
          </h6>
          <span class="badge bg-success-subtle text-success border border-success-subtle">Simulasi Bisnis</span>
        </div>
        <div class="p-3 bg-white rounded border border-success-subtle border-2">
          <div class="row g-3">
            <div class="col-12 col-md-6">
              <label class="form-label small fw-semibold">Nilai Taksiran Pasar (HPS Emas)</label>
              <InputNominalStart
                id="rc-nilai-taksiran"
                v-model="rcNilaiTaksiran"
                unit="Rp"
                placeholder="Masukkan nilai taksir..."
              />
            </div>
            <div class="col-12 col-md-6">
              <label class="form-label small fw-semibold">Maksimal Uang Pinjaman (85% HPS)</label>
              <InputNominalStart
                id="rc-uang-pinjaman"
                v-model="rcUangPinjaman"
                unit="Rp"
                :disabled="true"
              />
            </div>
          </div>
          <div class="mt-2 text-muted small">
            <span>Uang Pinjaman Bersih: <strong>Rp {{ formatRupiah(rcUangPinjaman) }}</strong> (setelah dipotong biaya administrasi)</span>
          </div>
        </div>
      </div>
    </div>
  </section>
</template>

<script setup>
import { ref, computed } from 'vue'
import InputNominalStart from '@/components/Input/InputNominalStart.vue'

const stateDefault = ref('')
const stateRp = ref('25000000')
const stateFilled = ref('50000000')
const stateDisabled = ref('12500000')

const rcNilaiTaksiran = ref('18000000')
const rcUangPinjaman = computed(() => {
  const num = parseInt(rcNilaiTaksiran.value, 10) || 0
  return String(Math.floor(num * 0.85))
})

const formatRupiah = (val) => {
  if (!val) return '0'
  return val.replace(/\B(?=(\d{3})+(?!\d))/g, '.')
}
</script>
