<script setup>
import { ref, computed } from 'vue'
import InputSearch from '@/components/Input/InputSearch.vue'
import Button from '@/components/Button/Button.vue'
import Badge from '@/components/Badge/Badge.vue'

const queryUmum = ref('')
const queryNIK = ref('3171025409880003')
const queryPrefilled = ref('0012984520')
const queryDisabled = ref('Gudang Simpanan Emas 01')

// Real Case Data
const rcPencarianNasabah = ref('')
const daftarNasabahMaster = [
  { sbg: '10234-26-01-000452', nama: 'Siti Rahmawati', nik: '3171 0456 0992 0001', barang: 'Kalung Emas 22K (8.50 gr)', up: 'Rp 7.200.000', status: 'Aktif' },
  { sbg: '10234-26-01-000453', nama: 'Budi Santoso', nik: '3201 1234 0588 0004', barang: 'Logam Mulia Antam (10.00 gr)', up: 'Rp 11.500.000', status: 'Aktif' },
  { sbg: '10234-26-01-000454', nama: 'Ahmad Fauzi', nik: '3578 0921 0485 0002', barang: 'Gelang Emas 18K (12.30 gr)', up: 'Rp 8.900.000', status: 'Jatuh Tempo' },
  { sbg: '10234-26-01-000455', nama: 'Dewi Lestari', nik: '3374 0812 0795 0007', barang: 'Cincin Berlian Solitaire (4.20 gr)', up: 'Rp 15.000.000', status: 'Aktif' }
]

const filteredNasabahList = computed(() => {
  if (!rcPencarianNasabah.value) return daftarNasabahMaster
  const q = rcPencarianNasabah.value.toLowerCase().replace(/\s+/g, '')
  return daftarNasabahMaster.filter(n =>
    n.nama.toLowerCase().includes(q) ||
    n.sbg.toLowerCase().includes(q) ||
    n.nik.replace(/\s+/g, '').includes(q) ||
    n.barang.toLowerCase().includes(q)
  )
})
</script>
