const searchQuery = ref('')
const isSearchOpen = ref(false)
const searchContainerRef = ref(null)

const totalComponents = computed(() => {
  return categories.reduce((sum, cat) => sum + cat.components.length, 0)
})

const allComponents = computed(() => {
  const list = []
  categories.forEach(cat => {
    cat.components.forEach(comp => {
      list.push({
        ...comp,
        categoryId: cat.id,
        categoryName: cat.shortName
      })
    })
  })
  return list
})

const isScrolled = ref(false)

const handleWindowScroll = () => {
  isScrolled.value = window.scrollY > 20
}

const filteredSearchResults = computed(() => {
  if (!searchQuery.value.trim()) return []
  const q = searchQuery.value.toLowerCase().trim()
  return allComponents.value.filter(c =>
    c.label.toLowerCase().includes(q) || c.categoryName.toLowerCase().includes(q)
  )
})

const scrollToCategory = (catId) => {
  activeCategoryId.value = catId
  const el = document.getElementById(catId)
  if (el) {
    el.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }
}

const scrollToComponent = (compId) => {
  if (!compId) return
  const comp = allComponents.value.find(c => c.id === compId)
  if (comp) {
    activeCategoryId.value = comp.categoryId
  }
  const el = document.getElementById(compId)
  if (el) {
    el.scrollIntoView({ behavior: 'smooth', block: 'start' })
    el.classList.add('component-highlight-pulse')
    setTimeout(() => {
      el.classList.remove('component-highlight-pulse')
    }, 2000)
  }
  searchQuery.value = ''
  isSearchOpen.value = false
}

const handleClickOutside = (event) => {
  if (searchContainerRef.value && !searchContainerRef.value.contains(event.target)) {
    isSearchOpen.value = false
  }
}

let observer = null

onMounted(() => {
  document.addEventListener('click', handleClickOutside)
  window.addEventListener('scroll', handleWindowScroll, { passive: true })

  // IntersectionObserver to auto-update activeCategoryId when scrolling
  observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const catId = entry.target.dataset.category || entry.target.id
        if (catId) {
          activeCategoryId.value = catId
        }
      }
    })
  }, {
    rootMargin: '-120px 0px -60% 0px'
  })

  categories.forEach(cat => {
    const catEl = document.getElementById(cat.id)
    if (catEl) observer.observe(catEl)

    cat.components.forEach(comp => {
      const compEl = document.getElementById(comp.id)
      if (compEl) {
        compEl.dataset.category = cat.id
        observer.observe(compEl)
      }
    })
  })
})

onUnmounted(() => {
  document.removeEventListener('click', handleClickOutside)
  window.removeEventListener('scroll', handleWindowScroll)
  if (observer) observer.disconnect()
})
</script>

