<script setup>
import { ref, computed } from 'vue'
import InputSearchQR from '@/components/Input/InputSearchQR.vue'
import Button from '@/components/Button/Button.vue'
import Badge from '@/components/Badge/Badge.vue'

const stateDefault = ref('')
const statePrefilled = ref('1023426010008892')
const stateDisabled = ref('1023426000000000')
const stateError = ref('999900001111')

const handleScanResult = (result) => {
  stateDefault.value = result
}

// Real Case
const rcNomorKredit = ref('1023426010008892')
const databaseSBK = {
  '1023426010008892': {
    nama: 'Hj. Mardiah Susanti',
    barang: 'Gelang Emas Kuning 24K (15.20 gr)',
    up: 'Rp 14.500.000',
    status: 'Lunas'
  },
  '1023426010008893': {
    nama: 'Bambang Pamungkas',
    barang: 'Logam Mulia Antam CertiCard (25.00 gr)',
    up: 'Rp 28.000.000',
    status: 'Aktif'
  }
}

const detailSbkTerpilih = computed(() => {
  const clean = rcNomorKredit.value ? rcNomorKredit.value.replace(/\s+/g, '') : ''
  return databaseSBK[clean] || null
})
</script>
