<script setup>
defineOptions({
  name: 'LoadAnimationSection'
})

import { ref } from 'vue'
import Load from '@/components/Modal/Load.vue'
import Button from '@/components/Button/Button.vue'

const showDefaultLoader = ref(false)
const showProgressLoader = ref(false)
const progressPercent = ref(0)
const showSyncLoader = ref(false)

const showRealCaseLoader = ref(false)
const realCaseProgress = ref(0)
const transferStatus = ref('Siap Diproses')

const triggerDefaultLoader = () => {
  showDefaultLoader.value = true
  setTimeout(() => {
    showDefaultLoader.value = false
  }, 2500)
}

const triggerProgressLoader = () => {
  showProgressLoader.value = true
  progressPercent.value = 0
  const interval = setInterval(() => {
    if (progressPercent.value < 100) {
      progressPercent.value += 20
    } else {
      clearInterval(interval)
      setTimeout(() => {
        showProgressLoader.value = false
      }, 500)
    }
  }, 300)
}

const triggerSyncLoader = () => {
  showSyncLoader.value = true
  setTimeout(() => {
    showSyncLoader.value = false
  }, 2500)
}

const startRealCaseTransfer = () => {
  showRealCaseLoader.value = true
  realCaseProgress.value = 10
  transferStatus.value = 'Sedang Mengirim Dana...'
  
  const stepInterval = setInterval(() => {
    if (realCaseProgress.value < 100) {
      realCaseProgress.value += 30
    } else {
      clearInterval(stepInterval)
      setTimeout(() => {
        showRealCaseLoader.value = false
        transferStatus.value = 'Selesai — Dana Berhasil Ditransfer'
      }, 600)
    }
  }, 400)
}
</script>

