      <!-- 1. TABEL PROPS & SLOTS YANG DIDUKUNG (FULL WIDTH VIA .props-table) -->
      <div class="mb-4">
        <h6 class="fw-semibold text-secondary small text-uppercase mb-2">1. Daftar Props & Slots yang Didukung</h6>
        <div class="table-responsive w-100 rounded border">
          <table class="props-table">
            <thead>
              <tr>
                <th style="width: 20%; min-width: 140px;">Item Name</th>
                <th style="width: 22%; min-width: 150px;">Type</th>
                <th style="width: 15%; min-width: 100px;">Default</th>
                <th style="min-width: 200px;">Keterangan</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td><code>buttonTitle</code></td>
                <td><code>String</code></td>
                <td><code>'Button'</code></td>
                <td>Teks label yang ditampilkan pada tombol aksi.</td>
              </tr>
              <tr>
                <td><code>#input</code></td>
                <td><code>Slot</code></td>
                <td>-</td>
                <td>Slot utama tempat meletakkan komponen input (InputText, InputNominal, dsb).</td>
              </tr>
              <tr>
                <td><code>@click</code></td>
                <td><code>Event</code></td>
                <td>-</td>
                <td>Event yang dipancarkan saat tombol aksi diklik oleh pengguna.</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      <!-- 2. VARIAN STATE KOMPONEN (3-5 VARIAN BERMAKNA) -->
      <div class="mb-4">
        <h6 class="fw-semibold text-secondary small text-uppercase mb-2">2. Varian State Komponen</h6>
        <div class="p-3 bg-light rounded border">
          <div class="row g-4">
            <!-- Varian 1: Default Text Input -->
            <div class="col-12 col-md-6">
              <label class="form-label small fw-semibold text-muted mb-1">Default Action ("Cek Data")</label>
              <InputWithActionButton
                button-title="Cek Data"
                @click="handleCheckDefault"
              >
                <template #input>
                  <InputText
                    id="action-default"
                    v-model="stateDefault"
                    placeholder="Ketik kata kunci pencarian..."
                    label="Pencarian Cepat Dokumen"
                  />
                </template>
              </InputWithActionButton>
              <div class="text-muted small mt-1">Status: <code>{{ statusDefault }}</code></div>
            </div>

            <!-- Varian 2: Tombol Verifikasi Kode Promo -->
            <div class="col-12 col-md-6">
              <label class="form-label small fw-semibold text-muted mb-1">Tombol "Terapkan Voucher"</label>
              <InputWithActionButton
                button-title="Terapkan"
                @click="handleApplyVoucher"
              >
                <template #input>
                  <InputText
                    id="action-voucher"
                    v-model="stateVoucher"
                    placeholder="Masukkan kode promo..."
                    label="Kupon Diskon Biaya Titip"
                    :use-auto-caps="true"
                  />
                </template>
              </InputWithActionButton>
              <div class="text-muted small mt-1">Status: <code>{{ statusVoucher }}</code></div>
            </div>
          </div>
        </div>
