      <!-- 3. REAL CASE: SIMULASI KONTEKS BISNIS PEGADAIAN -->
      <div>
        <div class="d-flex flex-column flex-sm-row align-items-start align-items-sm-center justify-content-between gap-2 mb-2">
          <h6 class="fw-bold text-success small text-uppercase mb-0">
            3. Real Case: Verifikasi Nomor Rekening Bank Nasabah untuk Pencairan Uang Pinjaman
          </h6>
          <span class="badge bg-success-subtle text-success border border-success-subtle">Simulasi Bisnis</span>
        </div>
        <div class="p-3 bg-white rounded border border-success-subtle border-2">
          <InputWithActionButton
            button-title="Validasi Rekening"
            @click="handleValidateBank"
          >
            <template #input>
              <InputText
                id="rc-rekening-nasabah"
                v-model="rcNoRekening"
                label="Nomor Rekening Bank BRI / Mandiri / BNI Nasabah"
                placeholder="Contoh: 0123-01-092831-50-2"
                helper-text="Rekening wajib berstatus aktif dan sesuai dengan nama nasabah"
              />
            </template>
          </InputWithActionButton>

          <div v-if="bankValidationResult" class="mt-3">
            <Alert color="green" :label="`✓ Rekening Valid: ${bankValidationResult}`" :hide-action="false">
              <template #action>
                <Badge type="primary" label="Nama Cocok" />
              </template>
            </Alert>
          </div>
        </div>
      </div>
    </div>
  </section>
</template>

<script setup>
import { ref } from 'vue'
import InputWithActionButton from '@/components/Input/InputWithActionButton.vue'
import InputText from '@/components/Input/InputText.vue'
import Alert from '@/components/Alert/AlertVarian.vue'
import Badge from '@/components/Badge/Badge.vue'

const stateDefault = ref('')
const statusDefault = ref('Siap mencari')

const stateVoucher = ref('GADAIBERKAH2026')
const statusVoucher = ref('Siap diterapkan')

const rcNoRekening = ref('012301092831502')
const bankValidationResult = ref('PT BANK RAKYAT INDONESIA - a.n. AHMAD ZULKARNAIN')

const handleCheckDefault = () => {
  statusDefault.value = `Mencari data untuk: "${stateDefault.value || 'semua'}"... Selesai!`
}

const handleApplyVoucher = () => {
  statusVoucher.value = `Kode [${stateVoucher.value}] Berhasil Diterapkan! Diskon Sewa Modal 20%`
}

const handleValidateBank = () => {
  bankValidationResult.value = `PT BANK RAKYAT INDONESIA - Rekening [${rcNoRekening.value}] a.n. AHMAD ZULKARNAIN (Status: Aktif)`
}
</script>
