<script setup>
import { ref, computed } from 'vue'
import FilterCMS from '@/components/Filter/FilterCMS.vue'
import Button from '@/components/Button/Button.vue'
import Badge from '@/components/Badge/Badge.vue'
import InputSearch from '@/components/Input/InputSearch.vue'
import Dropdown from '@/components/Dropdown/InputDropdown.vue'

// Date & Time Update (Sesuai GlobalComponent.vue)
const today = new Date()
const dateUpdate = today.toLocaleDateString('en-GB')
const timeUpdate = new Intl.DateTimeFormat('en-US', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: true
}).format(today)

// Varian 1 State & Options (6 Filter Direct Children Matrix 3x2)
const v1JenisPengajuan = ref('')
const v1KategoriAgunan = ref('')
const v1Kanwil = ref('')
const v1StatusOtorisasi = ref('')
const v1Query = ref('')
const v1MetodePelunasan = ref('')

const pengajuanOptions = [
  { value: '', text: 'Semua Pengajuan Kredit' },
  { value: 'kca', text: 'Gadai KCA (Kredit Cepat Aman)' },
  { value: 'krasida', text: 'Krasida (Angsuran Emas)' },
  { value: 'rahn', text: 'Rahn (Gadai Syariah)' }
]

const agunanOptions = [
  { value: '', text: 'Semua Kategori Agunan' },
  { value: 'emas', text: 'Logam Mulia & Perhiasan Emas' },
  { value: 'elektronik', text: 'Barang Elektronik & Gadget' },
  { value: 'kendaraan', text: 'Kendaraan Bermotor' }
]

const kanwilOptions = [
  { value: '', text: 'Semua Kantor Wilayah' },
  { value: 'kanwil8', text: 'Kanwil VIII Jakarta 1' },
  { value: 'kanwil9', text: 'Kanwil IX Jakarta 2' },
  { value: 'kanwil10', text: 'Kanwil X Bandung' }
]

const otorisasiOptions = [
  { value: '', text: 'Semua Status Otorisasi' },
  { value: 'disetujui', text: 'Disetujui Penaksir Senior' },
  { value: 'perlu_uji', text: 'Perlu Uji Karatase Ulang' },
  { value: 'ditolak', text: 'Ditolak / HPS Tidak Sesuai' }
]

const pembayaranOptions = [
  { value: '', text: 'Semua Metode Pembayaran' },
  { value: 'tunai', text: 'Tunai di Loket Kasir' },
  { value: 'transfer', text: 'Transfer Virtual Account (VA)' },
  { value: 'autodebet', text: 'Autodebet Tabungan Emas' }
]

// Varian 2 State & Options (Mode Ringkas 3 Filter)
const v2Search = ref('')
const v2Loket = ref('')
const v2StatusLayanan = ref('')

const loketOptions = [
  { value: '', text: 'Semua Loket UPK' },
  { value: 'loket1', text: 'Loket 01 - Kasir Emas' },
  { value: 'loket2', text: 'Loket 02 - Gadai Kilat' },
  { value: 'loket3', text: 'Loket 03 - Customer Care' }
]

// Real Case State & Options
const rcFilterQuery = ref('')
const rcFilterProduk = ref('')
const rcFilterStatus = ref('')

const produkOptions = [
  { value: '', text: 'Semua Produk Gadai' },
  { value: 'KCA', text: 'KCA (Kredit Cepat Aman)' },
  { value: 'Gadai Tabungan Emas', text: 'Gadai Tabungan Emas' },
  { value: 'Krasida', text: 'Krasida (Angsuran Bulanan)' }
]

const statusOptions = [
  { value: '', text: 'Semua Status' },
  { value: 'Lancar', text: 'Lancar' },
  { value: 'Mendekati Jatuh Tempo', text: 'Mendekati Jatuh Tempo' }
]

const masterOslData = [
  { id: 'OSL-2026-001', nasabah: 'Budi Darmawan', produk: 'KCA', up: 'Rp 12.000.000', status: 'Lancar' },
  { id: 'OSL-2026-002', nasabah: 'Siti Aminah', produk: 'Gadai Tabungan Emas', up: 'Rp 6.500.000', status: 'Lancar' },
  { id: 'OSL-2026-003', nasabah: 'Hendra Gunawan', produk: 'Krasida', up: 'Rp 25.000.000', status: 'Mendekati Jatuh Tempo' },
  { id: 'OSL-2026-004', nasabah: 'Ratna Sari Dewi', produk: 'KCA', up: 'Rp 5.000.000', status: 'Lancar' }
]

const filteredOslData = computed(() => {
  return masterOslData.filter(item => {
    const matchQ = !rcFilterQuery.value || item.nasabah.toLowerCase().includes(rcFilterQuery.value.toLowerCase())
    const matchP = !rcFilterProduk.value || item.produk === rcFilterProduk.value
    const matchS = !rcFilterStatus.value || item.status === rcFilterStatus.value
    return matchQ && matchP && matchS
  })
})

const resetRealCaseFilter = () => {
  rcFilterQuery.value = ''
  rcFilterProduk.value = ''
  rcFilterStatus.value = ''
}

const exportDataSimulasi = () => {
  alert(`Ekspor ${filteredOslData.value.length} data portofolio OSL sedang disiapkan...`)
}
</script>
